package br.com.gustavo.nossotempo;
import android.app.*;import android.content.*;
public class AnniversaryReceiver extends BroadcastReceiver{@Override public void onReceive(Context c,Intent source){String type=source.getStringExtra("type");NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("dates","Datas importantes",NotificationManager.IMPORTANCE_HIGH));if("day".equals(type)){Intent full=new Intent(c,CelebrationActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,9,full,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify(90,new Notification.Builder(c,"dates").setSmallIcon(R.drawable.app_icon).setContentTitle("Hoje é o dia de vocês! ♥").setContentText("Toque para abrir a comemoração.").setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_MAX).setFullScreenIntent(pi,true).setContentIntent(pi).setAutoCancel(true).build());}else nm.notify("10".equals(type)?91:92,new Notification.Builder(c,"dates").setSmallIcon(R.drawable.app_icon).setContentTitle("Faltam "+type+" dias ♥").setContentText("O próximo aniversário de namoro está chegando.").setAutoCancel(true).build());AnniversaryScheduler.scheduleAll(c);}}
